  CONSTRAINT "CK_NumberIssue_2" CHECK (("EntityType" IS NULL AND "EntityId" IS NULL) OR ("EntityType" IS NOT NULL AND "EntityId" IS NOT NULL)),
  CONSTRAINT "CK_NumberIssue_Status" CHECK ("Status" IS NULL OR "Status" IN ('ISSUED', 'VOID'))
);
