CREATE TABLE "cfg"."OutboxEvent" (
  "TenantId" integer NOT NULL,
  "OutboxEventId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "MessageId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "EventName" varchar(100) NOT NULL,
  "AggregateType" varchar(60) NULL,
  "AggregateId" bigint NULL,
  "PayloadJson" text NOT NULL,
  "OccurredAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "Status" varchar(10) NOT NULL DEFAULT 'PENDING',
  "AttemptCount" integer NOT NULL DEFAULT 0,
  "NextAttemptAt" timestamp(3) NULL,
  "LockedBy" varchar(60) NULL,
  "LockedUntil" timestamp(3) NULL,
  "DeliveredAt" timestamp(3) NULL,
  "LastError" varchar(1000) NULL,
  "CorrelationId" uuid NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("OutboxEventId"),
  CONSTRAINT "UQ_OutboxEvent_Tenant" UNIQUE ("TenantId", "OutboxEventId"),
  CONSTRAINT "UQ_OutboxEvent_MessageId" UNIQUE ("TenantId", "MessageId"),
  CONSTRAINT "CK_OutboxEvent_1" CHECK ("AttemptCount" >= 0),
  CONSTRAINT "CK_OutboxEvent_2" CHECK ("EventName" LIKE '%.%'),
  CONSTRAINT "CK_OutboxEvent_3" CHECK ("Status" <> 'PROCESSING' OR ("LockedBy" IS NOT NULL AND "LockedUntil" IS NOT NULL)),
  CONSTRAINT "CK_OutboxEvent_4" CHECK ("Status" <> 'DELIVERED' OR "DeliveredAt" IS NOT NULL),
  CONSTRAINT "CK_OutboxEvent_5" CHECK ("Status" <> 'DEAD' OR "LastError" IS NOT NULL),
  CONSTRAINT "CK_OutboxEvent_Status" CHECK ("Status" IS NULL OR "Status" IN ('PENDING', 'PROCESSING', 'DELIVERED', 'FAILED', 'DEAD'))
);
CREATE TABLE "cfg"."JobDefinition" (
  "JobDefinitionId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "JobKey" varchar(80) NOT NULL,
  "Scope" varchar(10) NOT NULL,
  "RunsInStatuses" varchar(49) NULL,
  "Description" varchar(500) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("JobDefinitionId"),
  CONSTRAINT "UQ_JobDefinition_JobKey" UNIQUE ("JobKey"),
  CONSTRAINT "CK_JobDefinition_1" CHECK ("Scope" = 'PLATFORM' OR "RunsInStatuses" IS NOT NULL),
  CONSTRAINT "CK_JobDefinition_Scope" CHECK ("Scope" IS NULL OR "Scope" IN ('TENANT', 'PLATFORM')),
  CONSTRAINT "CK_JobDefinition_RunsInStatuses" CHECK ("RunsInStatuses" IS NULL OR length("RunsInStatuses") + 1 = CASE WHEN position(',TRIAL,' in ',' || "RunsInStatuses" || ',') > 0 THEN 6 ELSE 0 END + CASE WHEN position(',ACTIVE,' in ',' || "RunsInStatuses" || ',') > 0 THEN 7 ELSE 0 END + CASE WHEN position(',SUSPENDED,' in ',' || "RunsInStatuses" || ',') > 0 THEN 10 ELSE 0 END + CASE WHEN position(',CLOSED,' in ',' || "RunsInStatuses" || ',') > 0 THEN 7 ELSE 0 END + CASE WHEN position(',ARCHIVED_READ_ONLY,' in ',' || "RunsInStatuses" || ',') > 0 THEN 19 ELSE 0 END)
);
CREATE TABLE "cfg"."JobRun" (
  "TenantId" integer NOT NULL,
