  "IsPrimary" smallint NOT NULL DEFAULT 0,
  CHECK ("IsPrimary" IS NULL OR "IsPrimary" IN (0,1)),
  "IsCurrent" smallint NOT NULL DEFAULT 1,
  CHECK ("IsCurrent" IS NULL OR "IsCurrent" IN (0,1)),
  "CountryId" integer NOT NULL,
  "Region" varchar(100) NULL,
  "City" varchar(100) NULL,
  "District" varchar(100) NULL,
  "Street" varchar(150) NULL,
  "BuildingNumber" varchar(20) NULL,
  "UnitNumber" varchar(20) NULL,
  "PostalCode" varchar(20) NULL,
  "AdditionalNumber" varchar(20) NULL,
  "ShortCode" varchar(20) NULL,
  "PoBoxNumber" varchar(30) NULL,
  "FreeText" varchar(500) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("AddressId"),
  CONSTRAINT "UQ_Address_Tenant" UNIQUE ("TenantId", "AddressId"),
