CREATE TABLE "ref"."Country" (
  "CountryId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Iso2" char(2) NOT NULL,
  "Iso3" char(3) NOT NULL,
  "NameAr" varchar(100) NOT NULL,
  "NameEn" varchar(100) NOT NULL,
  "IsGcc" smallint NOT NULL DEFAULT 0,
  CHECK ("IsGcc" IS NULL OR "IsGcc" IN (0,1)),
  "WeekendDays" varchar(40) NULL,
  "DialCode" varchar(8) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("CountryId"),
  CONSTRAINT "UQ_Country_Iso2" UNIQUE ("Iso2"),
  CONSTRAINT "UQ_Country_Iso3" UNIQUE ("Iso3"),
  CONSTRAINT "CK_Country_1" CHECK ("Iso2" NOT LIKE '%[^A-Z]%' AND "Iso3" NOT LIKE '%[^A-Z]%'),
  CONSTRAINT "CK_Country_2" CHECK ("DialCode" IS NULL OR ("DialCode" LIKE '+[0-9]%' AND "DialCode" NOT LIKE '+%[^0-9]%' AND "DialCode" NOT LIKE '+_____%')),
  CONSTRAINT "CK_Country_3" CHECK ("WeekendDays" IS NULL OR "WeekendDays" NOT LIKE '%[^A-Z,]%'),
  CONSTRAINT "CK_Country_WeekendDays" CHECK ("WeekendDays" IS NULL OR length("WeekendDays") + 1 = CASE WHEN position(',MON,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',TUE,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',WED,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',THU,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',FRI,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',SAT,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END + CASE WHEN position(',SUN,' in ',' || "WeekendDays" || ',') > 0 THEN 4 ELSE 0 END)
);
