  "NameEn" varchar(200) NULL,
  "Description" varchar(500) NULL,
  "AbbreviationAr" varchar(30) NULL,
  "AbbreviationEn" varchar(30) NULL,
  "CountryId" integer NULL,
  "DefaultBodyTypes" varchar(65) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "IsSystem" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSystem" IS NULL OR "IsSystem" IN (0,1)),
  "IsLocked" smallint NOT NULL DEFAULT 0,
  CHECK ("IsLocked" IS NULL OR "IsLocked" IN (0,1)),
  "SortOrder" integer NOT NULL DEFAULT 0,
  "SeedKey" varchar(80) NULL,
  "ExternalCode" varchar(80) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LegalEntityTypeId"),
  CONSTRAINT "UQ_LegalEntityType_Tenant" UNIQUE ("TenantId", "LegalEntityTypeId"),
  CONSTRAINT "UQ_LegalEntityType_Code_CountryId" UNIQUE ("TenantId", "Code", "CountryId"),
  CONSTRAINT "CK_LegalEntityType_1" CHECK ("Code" NOT LIKE '%[^A-Z0-9_]%' AND "Code" NOT LIKE '[0-9_]%'),
  CONSTRAINT "CK_LegalEntityType_2" CHECK (("IsLocked" = 0 OR ("IsSystem" = 1 AND "IsActive" = 1)) AND ("IsSystem" = 0 OR "NameEn" IS NOT NULL)),
  CONSTRAINT "CK_LegalEntityType_DefaultBodyTypes" CHECK ("DefaultBodyTypes" IS NULL OR length("DefaultBodyTypes") + 1 = CASE WHEN position(',BOARD_OF_DIRECTORS,' in ',' || "DefaultBodyTypes" || ',') > 0 THEN 19 ELSE 0 END + CASE WHEN position(',BOARD_OF_MANAGERS,' in ',' || "DefaultBodyTypes" || ',') > 0 THEN 18 ELSE 0 END + CASE WHEN position(',MANAGEMENT,' in ',' || "DefaultBodyTypes" || ',') > 0 THEN 11 ELSE 0 END + CASE WHEN position(',GENERAL_ASSEMBLY,' in ',' || "DefaultBodyTypes" || ',') > 0 THEN 17 ELSE 0 END)
);
CREATE TABLE "cat"."DocumentType" (
  "TenantId" integer NOT NULL,
  "DocumentTypeId" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Code" varchar(80) NOT NULL,
  "NameAr" varchar(200) NOT NULL,
  "NameEn" varchar(200) NULL,
  "Description" varchar(500) NULL,
  "IsActive" smallint NOT NULL DEFAULT 1,
  CHECK ("IsActive" IS NULL OR "IsActive" IN (0,1)),
  "IsSystem" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSystem" IS NULL OR "IsSystem" IN (0,1)),
  "IsLocked" smallint NOT NULL DEFAULT 0,
  CHECK ("IsLocked" IS NULL OR "IsLocked" IN (0,1)),
  "SortOrder" integer NOT NULL DEFAULT 0,
  "SeedKey" varchar(80) NULL,
  "ExternalCode" varchar(80) NULL,
  "AppliesTo" varchar(72) NOT NULL,
  "RequiresExpiry" smallint NOT NULL DEFAULT 0,
  CHECK ("RequiresExpiry" IS NULL OR "RequiresExpiry" IN (0,1)),
  "IsSensitive" smallint NOT NULL DEFAULT 0,
  CHECK ("IsSensitive" IS NULL OR "IsSensitive" IN (0,1)),
  "AllowedMime" text NULL,
  "MaxSizeMb" integer NULL,
  "RetentionYears" integer NULL,
  "MaxAgeDays" integer NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("DocumentTypeId"),
  CONSTRAINT "UQ_DocumentType_Tenant" UNIQUE ("TenantId", "DocumentTypeId"),
  CONSTRAINT "UQ_DocumentType_Code" UNIQUE ("TenantId", "Code"),
  CONSTRAINT "CK_DocumentType_1" CHECK ("Code" NOT LIKE '%[^A-Z0-9_]%' AND "Code" NOT LIKE '[0-9_]%'),
  CONSTRAINT "CK_DocumentType_2" CHECK (("IsLocked" = 0 OR ("IsSystem" = 1 AND "IsActive" = 1)) AND ("IsSystem" = 0 OR "NameEn" IS NOT NULL)),
  CONSTRAINT "CK_DocumentType_3" CHECK ("MaxSizeMb" IS NULL OR "MaxSizeMb" > 0),
  CONSTRAINT "CK_DocumentType_4" CHECK ("RetentionYears" IS NULL OR "RetentionYears" > 0),
  CONSTRAINT "CK_DocumentType_5" CHECK ("MaxAgeDays" IS NULL OR "MaxAgeDays" > 0),
  CONSTRAINT "CK_DocumentType_AppliesTo" CHECK ("AppliesTo" IS NULL OR length("AppliesTo") + 1 = CASE WHEN position(',COMPANY,' in ',' || "AppliesTo" || ',') > 0 THEN 8 ELSE 0 END + CASE WHEN position(',PARTY,' in ',' || "AppliesTo" || ',') > 0 THEN 6 ELSE 0 END + CASE WHEN position(',INSTITUTION,' in ',' || "AppliesTo" || ',') > 0 THEN 12 ELSE 0 END + CASE WHEN position(',FACILITY,' in ',' || "AppliesTo" || ',') > 0 THEN 9 ELSE 0 END + CASE WHEN position(',ACCOUNT,' in ',' || "AppliesTo" || ',') > 0 THEN 8 ELSE 0 END + CASE WHEN position(',SIGNATORY,' in ',' || "AppliesTo" || ',') > 0 THEN 10 ELSE 0 END + CASE WHEN position(',REQUEST,' in ',' || "AppliesTo" || ',') > 0 THEN 8 ELSE 0 END + CASE WHEN position(',LC,' in ',' || "AppliesTo" || ',') > 0 THEN 3 ELSE 0 END + CASE WHEN position(',GENERAL,' in ',' || "AppliesTo" || ',') > 0 THEN 8 ELSE 0 END)
);
