  "OperativeCalendar" varchar(10) NOT NULL DEFAULT 'GREGORIAN',
  "HijriAdjusted" smallint NOT NULL DEFAULT 0,
  CHECK ("HijriAdjusted" IS NULL OR "HijriAdjusted" IN (0,1)),
  "HijriAdjustReason" varchar(300) NULL,
  "PreviousFacilityId" bigint NULL,
  "LifecycleStatus" varchar(10) NOT NULL DEFAULT 'DRAFT',
  "LifecycleReason" varchar(500) NULL,
  "BankUnilateralRights" varchar(43) NULL,
  "NoticeDays" integer NULL,
  "UsageBlockOnBreach" smallint NOT NULL DEFAULT 0,
  CHECK ("UsageBlockOnBreach" IS NULL OR "UsageBlockOnBreach" IN (0,1)),
  "UsageBlockOnUnconfirmed" smallint NOT NULL DEFAULT 0,
  CHECK ("UsageBlockOnUnconfirmed" IS NULL OR "UsageBlockOnUnconfirmed" IN (0,1)),
  "AlertLeadDays" varchar(40) NULL,
  "ApprovedRevisionNo" integer NOT NULL DEFAULT 0,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("FacilityId"),
  CONSTRAINT "UQ_Facility_Tenant" UNIQUE ("TenantId", "FacilityId"),
  CONSTRAINT "UQ_Facility_Scope_PreviousFacilityId" UNIQUE ("TenantId", "PreviousFacilityId", "FacilityId"),
  CONSTRAINT "UQ_Facility_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "UQ_Facility_FacilityNo" UNIQUE ("TenantId", "FacilityNo"),
  CONSTRAINT "CK_Facility_1" CHECK ("ExpiryDate" >= "EffectiveFrom"),
  CONSTRAINT "CK_Facility_2" CHECK ("AgreementDate" IS NULL OR "AgreementDate" <= "EffectiveFrom"),
  CONSTRAINT "CK_Facility_3" CHECK ("TotalAmount" > 0),
  CONSTRAINT "CK_Facility_4" CHECK ("PreviousFacilityId" IS NULL OR "PreviousFacilityId" <> "FacilityId"),
  CONSTRAINT "CK_Facility_5" CHECK ("NoticeDays" IS NULL OR "NoticeDays" >= 0),
  CONSTRAINT "CK_Facility_6" CHECK ("BankUnilateralRights" IS NULL OR "BankUnilateralRights" NOT LIKE '%CHANGE_PRICING%' OR "NoticeDays" IS NOT NULL),
  CONSTRAINT "CK_Facility_7" CHECK ("HijriAdjusted" = 0 OR "HijriAdjustReason" IS NOT NULL),
  CONSTRAINT "CK_Facility_8" CHECK ("LifecycleStatus" NOT IN ('SUSPENDED','EXPIRED','TERMINATED') OR "LifecycleReason" IS NOT NULL),
  CONSTRAINT "CK_Facility_9" CHECK ("ApprovedRevisionNo" >= 0),
  CONSTRAINT "CK_Facility_10" CHECK ("LifecycleStatus" = 'DRAFT' OR "ApprovedRevisionNo" >= 1),
  CONSTRAINT "CK_Facility_11" CHECK ("AlertLeadDays" IS NULL OR "AlertLeadDays" NOT LIKE '%[^0-9,]%'),
  CONSTRAINT "CK_Facility_PrecedenceLanguage" CHECK ("PrecedenceLanguage" IS NULL OR "PrecedenceLanguage" IN ('AR', 'EN', 'EQUAL')),
  CONSTRAINT "CK_Facility_OperativeCalendar" CHECK ("OperativeCalendar" IS NULL OR "OperativeCalendar" IN ('GREGORIAN', 'HIJRI')),
  CONSTRAINT "CK_Facility_LifecycleStatus" CHECK ("LifecycleStatus" IS NULL OR "LifecycleStatus" IN ('DRAFT', 'ACTIVE', 'SUSPENDED', 'EXPIRED', 'TERMINATED', 'SUPERSEDED')),
  CONSTRAINT "CK_Facility_BankUnilateralRights" CHECK ("BankUnilateralRights" IS NULL OR length("BankUnilateralRights") + 1 = CASE WHEN position(',EXTEND,' in ',' || "BankUnilateralRights" || ',') > 0 THEN 7 ELSE 0 END + CASE WHEN position(',CHANGE_PRICING,' in ',' || "BankUnilateralRights" || ',') > 0 THEN 15 ELSE 0 END + CASE WHEN position(',CANCEL,' in ',' || "BankUnilateralRights" || ',') > 0 THEN 7 ELSE 0 END + CASE WHEN position(',REDUCE_LIMITS,' in ',' || "BankUnilateralRights" || ',') > 0 THEN 14 ELSE 0 END),
  CONSTRAINT "CK_Facility_AlertLeadDays" CHECK ("AlertLeadDays" IS NULL OR length("AlertLeadDays") + 1 = CASE WHEN position(',90,' in ',' || "AlertLeadDays" || ',') > 0 THEN 3 ELSE 0 END + CASE WHEN position(',60,' in ',' || "AlertLeadDays" || ',') > 0 THEN 3 ELSE 0 END + CASE WHEN position(',30,' in ',' || "AlertLeadDays" || ',') > 0 THEN 3 ELSE 0 END + CASE WHEN position(',15,' in ',' || "AlertLeadDays" || ',') > 0 THEN 3 ELSE 0 END + CASE WHEN position(',7,' in ',' || "AlertLeadDays" || ',') > 0 THEN 2 ELSE 0 END + CASE WHEN position(',0,' in ',' || "AlertLeadDays" || ',') > 0 THEN 2 ELSE 0 END)
);
