  CONSTRAINT "CK_LcDocumentClause_2" CHECK ("VersionNo" >= 1),
  CONSTRAINT "CK_LcDocumentClause_3" CHECK ("DefaultOriginals" IS NULL OR "DefaultOriginals" >= 0),
  CONSTRAINT "CK_LcDocumentClause_4" CHECK ("DefaultCopies" IS NULL OR "DefaultCopies" >= 0),
  CONSTRAINT "CK_LcDocumentClause_5" CHECK ("LegalReviewStatus" <> 'REVIEWED' OR ("ReviewedByText" IS NOT NULL AND "ReviewedOn" IS NOT NULL)),
  CONSTRAINT "CK_LcDocumentClause_Category" CHECK ("Category" IS NULL OR "Category" IN ('COMMERCIAL_INVOICE', 'DELIVERY_NOTE', 'TRANSPORT_SEA', 'TRANSPORT_AIR', 'TRANSPORT_ROAD', 'TRANSPORT_MULTIMODAL', 'INSURANCE', 'ORIGIN', 'PACKING', 'WEIGHT', 'BENEFICIARY_CERT', 'FCR', 'OTHER')),
  CONSTRAINT "CK_LcDocumentClause_Scope" CHECK ("Scope" IS NULL OR "Scope" IN ('ANY', 'DOMESTIC', 'INTERNATIONAL')),
  CONSTRAINT "CK_LcDocumentClause_LegalReviewStatus" CHECK ("LegalReviewStatus" IS NULL OR "LegalReviewStatus" IN ('UNREVIEWED', 'REVIEWED')),
  CONSTRAINT "CK_LcDocumentClause_Status" CHECK ("Status" IS NULL OR "Status" IN ('ACTIVE', 'RETIRED'))
);
