  "PlaceOfDispatch" varchar(150) NULL,
  "PlaceOfFinalDestination" varchar(150) NULL,
  "PortOfLoading" varchar(150) NULL,
  "PortOfDischarge" varchar(150) NULL,
  "AirportOfDeparture" varchar(150) NULL,
  "AirportOfDestination" varchar(150) NULL,
  "IncotermId" integer NULL,
  "IncotermPlace" varchar(150) NULL,
  "GoodsCategory" varchar(80) NULL,
  "GoodsDescription" varchar(2000) NULL,
  "SupplierProformaNo" varchar(60) NULL,
  "SupplierProformaDate" date NULL,
  "InsuranceResponsibility" varchar(21) NULL,
  "InsuranceMinPct" numeric(9,6) NULL,
