  CHECK ("InsurancePctStated" IS NULL OR "InsurancePctStated" IN (0,1)),
  "InsuranceClauses" varchar(300) NULL,
  "BankMayArrangeInsurance" smallint NULL,
  CHECK ("BankMayArrangeInsurance" IS NULL OR "BankMayArrangeInsurance" IN (0,1)),
  "AdditionalConditions" varchar(2000) NULL,
  "IsTransferable" smallint NULL,
  CHECK ("IsTransferable" IS NULL OR "IsTransferable" IN (0,1)),
  "AssignmentOfProceedsText" varchar(500) NULL,
  "LcTextLanguage" varchar(10) NOT NULL DEFAULT 'EN',
  "MarginPct" numeric(9,6) NULL,
  "DebitAuthorization" varchar(18) NULL,
  "MarginHeldCurrency" varchar(10) NULL,
  "FacilityAccountId" bigint NULL,
  "MarginSettlementAccountId" bigint NULL,
  "ChargesAccountId" bigint NULL,
  "PostDeferralFinancingDays" integer NULL,
  "BankSpecificClauses" text NULL,
  "PrevLcNumber" varchar(60) NULL,
  "PrevLcAmount" numeric(19,4) NULL,
  "PrevLcCurrencyId" integer NULL,
  "PrevLcUtilizedAmount" numeric(19,4) NULL,
  "PrevLcOpenedBy" varchar(200) NULL,
  "SnapshotHash" bytea NULL,
  "TreasuryHash" bytea NULL,
  "LockedAt" timestamp(3) NULL,
  "LockedBy" bigint NULL,
  "SupersedesTermsId" bigint NULL,
  "CopiedFromTermsId" bigint NULL,
  "ChangeReason" text NULL,
  "PublicId" uuid NOT NULL DEFAULT gen_random_uuid(),
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LcTermsId"),
  CONSTRAINT "UQ_LcTerms_Tenant" UNIQUE ("TenantId", "LcTermsId"),
  CONSTRAINT "UQ_LcTerms_Scope_LcClass_CurrencyId_TolerancePlusP_9a573ef3" UNIQUE ("TenantId", "LcClass", "CurrencyId", "TolerancePlusPct", "ToleranceMinusPct", "LcTermsId"),
  CONSTRAINT "UQ_LcTerms_Scope_Purpose_CurrencyId" UNIQUE ("TenantId", "Purpose", "CurrencyId", "LcTermsId"),
  CONSTRAINT "UQ_LcTerms_PublicId" UNIQUE ("PublicId"),
  CONSTRAINT "CK_LcTerms_1" CHECK ("VersionNo" >= 1),
  CONSTRAINT "CK_LcTerms_2" CHECK ("VersionNo" = 1 OR "SupersedesTermsId" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_3" CHECK ("SupersedesTermsId" IS NULL OR "SupersedesTermsId" <> "LcTermsId"),
  CONSTRAINT "CK_LcTerms_4" CHECK ("CopiedFromTermsId" IS NULL OR "CopiedFromTermsId" <> "LcTermsId"),
  CONSTRAINT "CK_LcTerms_5" CHECK (("Purpose" = 'PROFORMA' AND "OwnerType" IN ('REQUEST','PROFORMA')) OR ("Purpose" = 'APPLICATION' AND "OwnerType" = 'REQUEST') OR ("Purpose" IN ('ISSUED','RECEIVED') AND "OwnerType" = 'LETTER_OF_CREDIT') OR ("Purpose" = 'AMENDMENT' AND "OwnerType" IN ('REQUEST','AMENDMENT'))),
  CONSTRAINT "CK_LcTerms_6" CHECK (("Purpose" NOT IN ('APPLICATION','ISSUED') OR "LcClass" = 'PURCHASE') AND ("Purpose" NOT IN ('PROFORMA','RECEIVED') OR "LcClass" = 'SALES')),
  CONSTRAINT "CK_LcTerms_7" CHECK ("OwnerType" <> 'REQUEST' OR "OwnerId" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_8" CHECK ("Status" = 'DRAFT' OR ("SnapshotHash" IS NOT NULL AND "LockedAt" IS NOT NULL AND "LockedBy" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_9" CHECK ("TreasuryHash" IS NULL OR "SnapshotHash" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_10" CHECK ("Status" = 'DRAFT' OR ("LcType" IS NOT NULL AND "CurrencyId" IS NOT NULL AND "Amount" IS NOT NULL AND "ExpiryRule" IS NOT NULL AND "AmountInWordsAr" IS NOT NULL AND "AmountInWordsEn" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_11" CHECK ("Amount" IS NULL OR "Amount" > 0),
  CONSTRAINT "CK_LcTerms_12" CHECK ("TolerancePlusPct" BETWEEN 0 AND 100 AND "ToleranceMinusPct" BETWEEN 0 AND 100),
  CONSTRAINT "CK_LcTerms_13" CHECK ("Status" = 'DRAFT' OR "ToleranceMode" <> 'NONE' OR ("TolerancePlusPct" = 0 AND "ToleranceMinusPct" = 0)),
  CONSTRAINT "CK_LcTerms_14" CHECK ("Status" = 'DRAFT' OR "ToleranceMode" <> 'ABOUT' OR ("TolerancePlusPct" = 10 AND "ToleranceMinusPct" = 10)),
  CONSTRAINT "CK_LcTerms_15" CHECK ("DeferralDays" IS NULL OR "DeferralDays" BETWEEN 1 AND 720),
  CONSTRAINT "CK_LcTerms_16" CHECK ("Status" = 'DRAFT' OR "LcType" <> 'SIGHT' OR ("DeferralDays" IS NULL AND "MaturityBasis" IS NULL)),
  CONSTRAINT "CK_LcTerms_17" CHECK ("Status" = 'DRAFT' OR "LcType" NOT IN ('DEFERRED_PAYMENT','ACCEPTANCE') OR ("DeferralDays" IS NOT NULL AND "MaturityBasis" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_18" CHECK ("Status" = 'DRAFT' OR "LcType" <> 'MIXED' OR "MixedPaymentText" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_19" CHECK ("Status" = 'DRAFT' OR "DraftDrawee" IS NULL OR ("DraftRequired" IS NOT NULL AND "DraftRequired" = 1)),
  CONSTRAINT "CK_LcTerms_20" CHECK ("Status" = 'DRAFT' OR "LcType" NOT IN ('ACCEPTANCE','NEGOTIATION') OR ("DraftRequired" IS NOT NULL AND "DraftRequired" = 1)),
  CONSTRAINT "CK_LcTerms_21" CHECK ("Status" = 'DRAFT' OR "ConfirmingBankBic" IS NULL OR (("ConfirmingBankBic" LIKE '________' OR "ConfirmingBankBic" LIKE '___________') AND "ConfirmingBankBic" NOT LIKE '%[^A-Z0-9]%')),
  CONSTRAINT "CK_LcTerms_22" CHECK ("Status" = 'DRAFT' OR "AdvisingBankBic" IS NULL OR (("AdvisingBankBic" LIKE '________' OR "AdvisingBankBic" LIKE '___________') AND "AdvisingBankBic" NOT LIKE '%[^A-Z0-9]%')),
  CONSTRAINT "CK_LcTerms_23" CHECK (("BeneficiaryAccountIbanEnc" IS NULL AND "BeneficiaryAccountIbanMask" IS NULL AND "BeneficiaryAccountIbanHash" IS NULL) OR ("BeneficiaryAccountIbanEnc" IS NOT NULL AND "BeneficiaryAccountIbanMask" IS NOT NULL AND "BeneficiaryAccountIbanHash" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_24" CHECK ("BeneficiaryAccountIbanEnc" IS NULL OR ("EncKeyId" IS NOT NULL AND "HashKeyId" IS NOT NULL AND octet_length("BeneficiaryAccountIbanEnc") >= 29)),
  CONSTRAINT "CK_LcTerms_25" CHECK ("LcClass" = 'SALES' OR ("ApplicantCounterpartyId" IS NULL AND "BeneficiaryCompanyId" IS NULL)),
  CONSTRAINT "CK_LcTerms_26" CHECK ("LcClass" = 'PURCHASE' OR ("ApplicantCompanyId" IS NULL AND "BeneficiaryCounterpartyId" IS NULL)),
  CONSTRAINT "CK_LcTerms_27" CHECK ("Status" = 'DRAFT' OR ("LcClass" = 'PURCHASE' AND "ApplicantCompanyId" IS NOT NULL AND "BeneficiaryCounterpartyId" IS NOT NULL) OR ("LcClass" = 'SALES' AND "ApplicantCounterpartyId" IS NOT NULL AND "BeneficiaryCompanyId" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_28" CHECK ("ExpiryDaysAfterIssue" IS NULL OR "ExpiryDaysAfterIssue" > 0),
  CONSTRAINT "CK_LcTerms_29" CHECK ("LatestShipmentDaysAfterIssue" IS NULL OR "LatestShipmentDaysAfterIssue" > 0),
  CONSTRAINT "CK_LcTerms_30" CHECK ("Status" = 'DRAFT' OR "ExpiryRule" IS NULL OR ("ExpiryRule" = 'ABSOLUTE' AND "ExpiryDate" IS NOT NULL AND "ExpiryDaysAfterIssue" IS NULL) OR ("ExpiryRule" = 'DAYS_AFTER_ISSUE' AND "ExpiryDaysAfterIssue" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_31" CHECK ("Status" = 'DRAFT' OR ("LatestShipmentRule" IS NULL AND "LatestShipmentDate" IS NULL AND "LatestShipmentDaysAfterIssue" IS NULL) OR ("LatestShipmentRule" = 'ABSOLUTE' AND "LatestShipmentDate" IS NOT NULL AND "LatestShipmentDaysAfterIssue" IS NULL) OR ("LatestShipmentRule" = 'DAYS_AFTER_ISSUE' AND "LatestShipmentDaysAfterIssue" IS NOT NULL)),
  CONSTRAINT "CK_LcTerms_32" CHECK ("Status" = 'DRAFT' OR "Purpose" IN ('ISSUED','RECEIVED') OR "EarliestShipmentDate" IS NULL OR "LatestShipmentDate" IS NULL OR "EarliestShipmentDate" <= "LatestShipmentDate"),
  CONSTRAINT "CK_LcTerms_33" CHECK ("Status" = 'DRAFT' OR "Purpose" IN ('ISSUED','RECEIVED') OR "ExpiryDate" IS NULL OR "LatestShipmentDate" IS NULL OR "ExpiryDate" >= "LatestShipmentDate"),
  CONSTRAINT "CK_LcTerms_34" CHECK ("PresentationDays" IS NULL OR "PresentationDays" BETWEEN 1 AND 90),
  CONSTRAINT "CK_LcTerms_35" CHECK ("Status" = 'DRAFT' OR "Purpose" IN ('ISSUED','RECEIVED') OR "IncotermId" IS NULL OR "IncotermPlace" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_36" CHECK ("InsurancePctStated" = 0 OR "InsuranceMinPct" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_37" CHECK ("InsuranceMinPct" IS NULL OR "InsuranceMinPct" > 0),
  CONSTRAINT "CK_LcTerms_38" CHECK ("MarginPct" IS NULL OR "MarginPct" BETWEEN 0 AND 100),
  CONSTRAINT "CK_LcTerms_39" CHECK ("Status" = 'DRAFT' OR "DebitAuthorization" IS NULL OR "DebitAuthorization" <> 'FULL_LC_VALUE' OR ("MarginPct" IS NOT NULL AND "MarginPct" = 100)),
  CONSTRAINT "CK_LcTerms_40" CHECK ("PostDeferralFinancingDays" IS NULL OR "PostDeferralFinancingDays" >= 0),
  CONSTRAINT "CK_LcTerms_41" CHECK ("PrevLcAmount" IS NULL OR "PrevLcAmount" >= 0),
  CONSTRAINT "CK_LcTerms_42" CHECK ("PrevLcUtilizedAmount" IS NULL OR "PrevLcUtilizedAmount" >= 0),
  CONSTRAINT "CK_LcTerms_43" CHECK ("PrevLcAmount" IS NULL OR "PrevLcUtilizedAmount" IS NULL OR "PrevLcUtilizedAmount" <= "PrevLcAmount"),
  CONSTRAINT "CK_LcTerms_44" CHECK (("PrevLcAmount" IS NULL AND "PrevLcUtilizedAmount" IS NULL) OR "PrevLcCurrencyId" IS NOT NULL),
  CONSTRAINT "CK_LcTerms_OwnerType" CHECK ("OwnerType" IS NULL OR "OwnerType" IN ('REQUEST', 'PROFORMA', 'LETTER_OF_CREDIT', 'AMENDMENT')),
  CONSTRAINT "CK_LcTerms_Purpose" CHECK ("Purpose" IS NULL OR "Purpose" IN ('PROFORMA', 'APPLICATION', 'ISSUED', 'RECEIVED', 'AMENDMENT')),
  CONSTRAINT "CK_LcTerms_Status" CHECK ("Status" IS NULL OR "Status" IN ('DRAFT', 'LOCKED', 'SUPERSEDED')),
  CONSTRAINT "CK_LcTerms_LcClass" CHECK ("LcClass" IS NULL OR "LcClass" IN ('PURCHASE', 'SALES')),
  CONSTRAINT "CK_LcTerms_Scope" CHECK ("Scope" IS NULL OR "Scope" IN ('DOMESTIC', 'INTERNATIONAL')),
  CONSTRAINT "CK_LcTerms_UcpVersion" CHECK ("UcpVersion" IS NULL OR "UcpVersion" IN ('UCP600')),
  CONSTRAINT "CK_LcTerms_LcType" CHECK ("LcType" IS NULL OR "LcType" IN ('SIGHT', 'DEFERRED_PAYMENT', 'ACCEPTANCE', 'NEGOTIATION', 'MIXED')),
  CONSTRAINT "CK_LcTerms_MaturityBasis" CHECK ("MaturityBasis" IS NULL OR "MaturityBasis" IN ('SHIPMENT_DATE', 'DELIVERY_NOTE_DATE', 'INVOICE_DATE', 'DOCUMENTS_RECEIPT_DATE', 'ACCEPTANCE_DATE')),
  CONSTRAINT "CK_LcTerms_AvailableWith" CHECK ("AvailableWith" IS NULL OR "AvailableWith" IN ('ISSUING_BANK', 'ADVISING_BANK', 'NOMINATED_BANK', 'ANY_BANK')),
  CONSTRAINT "CK_LcTerms_DraftDrawee" CHECK ("DraftDrawee" IS NULL OR "DraftDrawee" IN ('ISSUING_BANK', 'ADVISING_BANK', 'CONFIRMING_BANK')),
  CONSTRAINT "CK_LcTerms_Confirmation" CHECK ("Confirmation" IS NULL OR "Confirmation" IN ('CONFIRMED', 'MAY_ADD', 'WITHOUT')),
  CONSTRAINT "CK_LcTerms_EncKeyPurpose" CHECK ("EncKeyPurpose" IS NULL OR "EncKeyPurpose" IN ('DATA')),
  CONSTRAINT "CK_LcTerms_HashKeyPurpose" CHECK ("HashKeyPurpose" IS NULL OR "HashKeyPurpose" IN ('BLIND_INDEX')),
  CONSTRAINT "CK_LcTerms_ToleranceMode" CHECK ("ToleranceMode" IS NULL OR "ToleranceMode" IN ('NONE', 'ABOUT', 'PLUS_MINUS')),
  CONSTRAINT "CK_LcTerms_ExpiryRule" CHECK ("ExpiryRule" IS NULL OR "ExpiryRule" IN ('ABSOLUTE', 'DAYS_AFTER_ISSUE')),
  CONSTRAINT "CK_LcTerms_LatestShipmentRule" CHECK ("LatestShipmentRule" IS NULL OR "LatestShipmentRule" IN ('ABSOLUTE', 'DAYS_AFTER_ISSUE')),
  CONSTRAINT "CK_LcTerms_PresentationBasis" CHECK ("PresentationBasis" IS NULL OR "PresentationBasis" IN ('SHIPMENT_DATE', 'DELIVERY_NOTE_DATE', 'INVOICE_DATE')),
  CONSTRAINT "CK_LcTerms_PartialShipments" CHECK ("PartialShipments" IS NULL OR "PartialShipments" IN ('ALLOWED', 'NOT_ALLOWED')),
  CONSTRAINT "CK_LcTerms_Transhipment" CHECK ("Transhipment" IS NULL OR "Transhipment" IN ('ALLOWED', 'NOT_ALLOWED', 'NOT_APPLICABLE')),
  CONSTRAINT "CK_LcTerms_TransportMode" CHECK ("TransportMode" IS NULL OR "TransportMode" IN ('SEA', 'AIR', 'ROAD', 'RAIL', 'COURIER', 'MULTIMODAL', 'DOMESTIC_DELIVERY')),
  CONSTRAINT "CK_LcTerms_InsuranceResponsibility" CHECK ("InsuranceResponsibility" IS NULL OR "InsuranceResponsibility" IN ('BENEFICIARY', 'APPLICANT', 'NOT_REQUIRED_BY_TERMS')),
  CONSTRAINT "CK_LcTerms_LcTextLanguage" CHECK ("LcTextLanguage" IS NULL OR "LcTextLanguage" IN ('EN', 'AR', 'BOTH')),
  CONSTRAINT "CK_LcTerms_DebitAuthorization" CHECK ("DebitAuthorization" IS NULL OR "DebitAuthorization" IN ('CHARGES_AND_MARGIN', 'FULL_LC_VALUE')),
  CONSTRAINT "CK_LcTerms_MarginHeldCurrency" CHECK ("MarginHeldCurrency" IS NULL OR "MarginHeldCurrency" IN ('LOCAL', 'FOREIGN'))
);
CREATE TABLE "lc"."LcTermsDocument" (
  "TenantId" integer NOT NULL,
  "LcTermsDocumentId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "LcTermsId" bigint NOT NULL,
  "SeqNo" integer NOT NULL,
  "ClauseId" bigint NOT NULL,
  "ClauseVersion" integer NOT NULL,
  "Originals" integer NULL,
  "Copies" integer NULL,
  "ParamsJson" text NULL,
  "RenderedTextEn" text NULL,
  "RenderedTextAr" text NULL,
  "IsFreeText" smallint NOT NULL DEFAULT 0,
  CHECK ("IsFreeText" IS NULL OR "IsFreeText" IN (0,1)),
  "FreeText" text NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
