CREATE TABLE "lc"."LcChargesMatrix" (
  "TenantId" integer NOT NULL,
  "LcChargesMatrixId" bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "LcTermsId" bigint NOT NULL,
  "ChargeCategory" varchar(22) NOT NULL,
  "Payer" varchar(11) NOT NULL,
  "ApplicantSharePct" numeric(9,6) NULL,
  "PresetCode" varchar(30) NULL,
  "Note" varchar(500) NULL,
  "CreatedAt" timestamp(3) NOT NULL DEFAULT (now() at time zone 'utc'),
  "CreatedBy" bigint NULL,
  "UpdatedAt" timestamp(3) NULL,
  "UpdatedBy" bigint NULL,
  PRIMARY KEY ("LcChargesMatrixId"),
  CONSTRAINT "UQ_LcChargesMatrix_Tenant" UNIQUE ("TenantId", "LcChargesMatrixId"),
  CONSTRAINT "UQ_LcChargesMatrix_LcTermsId_ChargeCategory" UNIQUE ("TenantId", "LcTermsId", "ChargeCategory"),
  CONSTRAINT "CK_LcChargesMatrix_1" CHECK ("Payer" <> 'SHARED' OR ("ApplicantSharePct" IS NOT NULL AND "ApplicantSharePct" > 0 AND "ApplicantSharePct" < 100)),
  CONSTRAINT "CK_LcChargesMatrix_2" CHECK ("Payer" = 'SHARED' OR "ApplicantSharePct" IS NULL),
  CONSTRAINT "CK_LcChargesMatrix_ChargeCategory" CHECK ("ChargeCategory" IS NULL OR "ChargeCategory" IN ('ISSUING_BANK_LOCAL', 'ADVISING', 'CONFIRMATION', 'NEGOTIATION_SETTLEMENT', 'AMENDMENT', 'OTHER_OUTSIDE_ISSUING')),
  CONSTRAINT "CK_LcChargesMatrix_Payer" CHECK ("Payer" IS NULL OR "Payer" IN ('APPLICANT', 'BENEFICIARY', 'SHARED'))
);
